package com.nexusplay.player;
import android.net.Uri;import android.os.Bundle;import android.view.Gravity;import android.view.WindowManager;import android.widget.FrameLayout;import android.widget.TextView;import android.widget.Toast;import androidx.appcompat.app.AppCompatActivity;import androidx.media3.common.MediaItem;import androidx.media3.common.PlaybackException;import androidx.media3.common.Player;import androidx.media3.exoplayer.ExoPlayer;import androidx.media3.ui.PlayerView;
public class PlayerActivity extends AppCompatActivity {private ExoPlayer player;private PlayerView playerView;
 @Override protected void onCreate(Bundle state){super.onCreate(state);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);getWindow().setStatusBarColor(0xFF000000);getWindow().setNavigationBarColor(0xFF000000);Uri uri=getIntent().getData();if(uri==null){finish();return;}FrameLayout root=new FrameLayout(this);root.setBackgroundColor(0xFF000000);playerView=new PlayerView(this);playerView.setUseController(true);playerView.setShowBuffering(PlayerView.SHOW_BUFFERING_WHEN_PLAYING);root.addView(playerView,new FrameLayout.LayoutParams(-1,-1));TextView back=new TextView(this);back.setText("‹  BACK");back.setTextColor(0xFFFFFFFF);back.setTextSize(13);back.setPadding(24,18,20,18);back.setBackgroundColor(0x66000000);root.addView(back,new FrameLayout.LayoutParams(-2,-2,Gravity.TOP|Gravity.START));back.setOnClickListener(v->finish());setContentView(root);player=new ExoPlayer.Builder(this).build();playerView.setPlayer(player);player.setMediaItem(MediaItem.fromUri(uri));player.prepare();player.play();player.addListener(new Player.Listener(){@Override public void onPlayerError(PlaybackException error){Toast.makeText(PlayerActivity.this,"This format or codec may not be supported on this device.",Toast.LENGTH_LONG).show();}});}
 @Override protected void onStop(){super.onStop();if(player!=null)player.pause();}@Override protected void onDestroy(){if(player!=null){playerView.setPlayer(null);player.release();player=null;}super.onDestroy();}
}
